#!/usr/bin/env node
// Builds the per-year form lines of the ELSTER fill-in help (ADR-0101 §16) from the official PDFs:
// downloads the BMF letters (download-formulare.mjs), reads the numbered rows (pdf-lines.mjs),
// keeps the rows spec.mjs names and writes them to packages/core as data. Run it after a new form
// year is published; then review the diff of the generated file like a Lagebericht.
//
//   node scripts/elster-lines/build-elster-lines.mjs [--out <pdf cache dir>] [--check]
//
// --check exits non-zero when the generated file would change (for CI or a quick review).
import { readFile, writeFile } from 'node:fs/promises'
import path from 'node:path'
import { DEFAULT_CACHE, ROOT, ensureSources, sha256 } from './download-formulare.mjs'
import { extractForm } from './pdf-lines.mjs'
import { ensureHelp } from './elster-help.mjs'
import { EUER_SECTIONS, EUER_SKIP, EUER_UNNUMBERED, HELP_SPECS, LINE_SPECS } from './spec.mjs'

const OUT = path.join(ROOT, 'packages/core/src/domains/business/elster-lines/lines.generated.ts')

// The forms print "Überschuss" and the small "bitte dem Betrag ein Minuszeichen voranstellen" with
// no space in the text layer.
const clean = (label) => label.replace(/(Überschuss|Erstattungsanspruch)(?=bitte)/g, '$1 – ')

function euerRows(rows, year) {
  const out = []
  let section
  for (const row of rows) {
    for (const h of row.headings) {
      const hit = EUER_SECTIONS.find((s) => s.heading.test(h))
      if (hit) section = hit.id
    }
    if (!section) continue
    if (row.kz.length === 0 && EUER_SKIP.test(withoutParenthesis(row.label))) continue
    let key
    if (row.kz.length > 0) key = `kz${row.kz[0]}`
    else key = EUER_UNNUMBERED.find(([re]) => re.test(row.label))?.[1]
    if (!key) throw new Error(`euer ${year} Zeile ${row.zeile}: no id for unnumbered row "${row.label}"; add it to EUER_UNNUMBERED`)
    out.push({ id: `euer.${section}.${key}`, zeile: row.zeile, kz: row.kz, label: clean(row.label) })
  }
  return out
}

function specRows(form, rows, year) {
  const out = []
  for (const spec of LINE_SPECS[form]) {
    const hits = rows.filter((r) => {
      const byKz = spec.kz ? r.kz.includes(spec.kz) : undefined
      const byLabel = spec.label ? spec.label.test(r.label) : undefined
      const byOther = spec.other ? spec.other.test(r.others.join(' ')) : undefined
      const tests = [byKz, byLabel, byOther].filter((t) => t !== undefined)
      return spec.either ? tests.some(Boolean) : tests.every(Boolean)
    })
    if (hits.length > 1) throw new Error(`${form} ${year}: ${spec.id} matches Zeilen ${hits.map((h) => h.zeile).join(', ')}`)
    const [row] = hits
    if (!row) continue
    const label = spec.other ? row.others.join(' ') : row.label
    out.push({ id: spec.id, zeile: row.zeile, kz: spec.other ? [] : row.kz, label: clean(label) })
  }
  return out
}

/** The label up to its first parenthesis, trimmed (a pattern for this backtracked on long labels). */
const withoutParenthesis = (label) => (label.includes('(') ? label.slice(0, label.indexOf('(')) : label).trimEnd()

function render(data, sources) {
  const lines = [
    '// Generated by scripts/elster-lines/build-elster-lines.mjs from the official PDFs listed in',
    '// docs/research/self-employed-forms.html. Do not edit: change scripts/elster-lines/spec.mjs and rebuild.',
    '',
    "import type { ExtractedLine } from './types'",
    '',
    '// One JSON string per form: rows of a form repeat from year to year, and as code they read as',
    '// duplicated blocks to the duplication check; as data they are what they are.',
    'const DATA: Readonly<Record<string, string>> = {',
  ]
  for (const [form, years] of Object.entries(data)) lines.push(`  ${JSON.stringify(form)}: ${JSON.stringify(JSON.stringify(years))},`)
  lines.push(
    '}',
    '',
    '/** Per form and tax year: the rows read from that year\'s PDF, in form order. */',
    'export const EXTRACTED_LINES: Readonly<Record<string, Readonly<Record<number, readonly ExtractedLine[]>>>> = Object.fromEntries(',
    '  Object.entries(DATA).map(([form, json]) => [form, JSON.parse(json) as Record<number, readonly ExtractedLine[]>]),',
    ')',
    '',
  )
  lines.push('/** SHA-256 of the PDF each year was read from, to tell a re-published form from the one checked here. */')
  lines.push('export const SOURCE_SHA256: Readonly<Record<string, Readonly<Record<number, string>>>> = {')
  for (const [form, years] of Object.entries(sources)) {
    lines.push(`  ${JSON.stringify(form)}: { ${Object.entries(years).map(([y, h]) => `${y}: '${h}'`).join(', ')} },`)
  }
  lines.push('}', '')
  return lines.join('\n')
}

const outIndex = process.argv.indexOf('--out')
const cacheDir = outIndex === -1 ? DEFAULT_CACHE : process.argv[outIndex + 1]
const data = {}
const sources = {}
for (const s of await ensureSources(cacheDir)) {
  const rows = extractForm(s.file, s.form)
  const picked = s.form === 'euer' ? euerRows(rows, s.year) : specRows(s.form, rows, s.year)
  const ids = new Set()
  for (const r of picked) {
    if (ids.has(r.id)) throw new Error(`${s.form} ${s.year}: duplicate id ${r.id}`)
    ids.add(r.id)
  }
  ;(data[s.form] ??= {})[s.year] = picked
  ;(sources[s.form] ??= {})[s.year] = sha256(await readFile(s.file))
  console.log(`[elster-lines] ${s.form} ${s.year}: ${picked.length} lines`)
}
for (const h of await ensureHelp(cacheDir)) {
  const picked = []
  for (const spec of HELP_SPECS[h.form]) {
    const box = spec.boxes.find((b) => h.help.boxes.has(b))
    if (box) picked.push({ id: spec.id, zeile: null, kz: [], label: h.help.boxes.get(box) })
  }
  ;(data[h.form] ??= {})[h.year] = picked
  ;(sources[h.form] ??= {})[h.year] = h.sha256
  console.log(`[elster-lines] ${h.form} ${h.year} (ELSTER-Hilfe): ${picked.length} fields`)
}
const text = render(data, sources)
if (process.argv.includes('--check')) {
  const current = await readFile(OUT, 'utf8').catch(() => '')
  if (current !== text) {
    console.error('[elster-lines] lines.generated.ts is out of date')
    process.exit(1)
  }
} else {
  await writeFile(OUT, text)
  console.log(`[elster-lines] wrote ${path.relative(ROOT, OUT)}`)
}
